using GestionMagasin.Application;
using GestionMagasin.Domain;

namespace GestionMagasin.WinForms;

public sealed class MainForm : Form
{
    readonly Panel content=new(){Dock=DockStyle.Fill,Padding=new Padding(18),BackColor=Color.White}; readonly Utilisateur user; readonly ProduitService products; readonly StockService stock; readonly UtilisateurService users; readonly ICategorieRepository categories; readonly IProduitRepository productRepository; readonly VenteService sales; readonly IUtilisateurRepository userRepository; readonly ReportingService reporting; readonly ParametresService settings; readonly SauvegardeService backup;
    public MainForm(Utilisateur user,string databasePath,ProduitService products,StockService stock,UtilisateurService users,ICategorieRepository categories,IProduitRepository productRepository,VenteService sales,IUtilisateurRepository userRepository,ReportingService reporting,ParametresService settings,SauvegardeService backup){this.user=user;this.products=products;this.stock=stock;this.users=users;this.categories=categories;this.productRepository=productRepository;this.sales=sales;this.userRepository=userRepository;this.reporting=reporting;this.settings=settings;this.backup=backup;Text="Gestion Magasin";MinimumSize=new Size(1050,650);WindowState=FormWindowState.Maximized;Font=new Font("Segoe UI",10);var nav=new FlowLayoutPanel{Dock=DockStyle.Left,Width=220,FlowDirection=FlowDirection.TopDown,WrapContents=false,BackColor=Color.FromArgb(35,45,58),Padding=new Padding(12)};Controls.Add(content);Controls.Add(nav);nav.Controls.Add(new Label{Text="GESTION\nMAGASIN",ForeColor=Color.White,Font=new Font("Segoe UI",16,FontStyle.Bold),Height=72,Width=190});nav.Controls.Add(new Label{Text=$"{user.NomComplet}\n{user.Role}",ForeColor=Color.Gainsboro,Height=52,Width=190});Action<string> open=title=>{if(title.Contains("vente",StringComparison.OrdinalIgnoreCase))Show(new SalesHistoryPanel(user,sales));else Show(new InventoryPanel(user,products,stock));};AddNav(nav,"Tableau de bord",()=>Show(new DashboardPanel(user,reporting,open)));AddNav(nav,"Nouvelle vente",()=>Show(new SalePanel(user,sales,products)));AddNav(nav,"Historique ventes",()=>Show(new SalesHistoryPanel(user,sales)));AddNav(nav,"Produits",()=>Show(new ProductsPanel(user,products,categories,productRepository)));AddNav(nav,"Catégories",()=>Show(new CategoriesPanel(user,categories)));AddNav(nav,"Stock",()=>Show(new StockPanel(user,products,stock)));AddNav(nav,"Inventaire",()=>Show(new InventoryPanel(user,products,stock)));if(user.Role==Roles.Administrateur){AddNav(nav,"Rapports",()=>Show(new ReportsPanel(user,reporting,settings,sales)));AddNav(nav,"Paramètres / sauvegarde",()=>Show(new SettingsPanel(user,settings,backup)));AddNav(nav,"Utilisateurs",()=>Show(new UsersPanel(user,users)));}Show(new DashboardPanel(user,reporting,open));}
    void AddNav(Control parent,string text,Action click){var b=new Button{Text=text,Width=190,Height=42,FlatStyle=FlatStyle.Flat,ForeColor=Color.White,BackColor=Color.FromArgb(48,62,80),Margin=new Padding(0,4,0,4)};b.FlatAppearance.BorderSize=0;b.Click+=(_,_)=>click();parent.Controls.Add(b);}
    void Show(Control page){content.Controls.Clear();page.Dock=DockStyle.Fill;content.Controls.Add(page);}
}

public sealed class FirstAdminForm : Form
{
    readonly AuthentificationService auth; readonly TextBox login=new(),name=new(),password=new(); public Utilisateur? User{get;private set;}
    public FirstAdminForm(AuthentificationService auth){this.auth=auth;Text="Premier démarrage";Width=480;Height=350;StartPosition=FormStartPosition.CenterScreen;var p=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(25),ColumnCount=2,RowCount=5};p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,35));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,65));Add(p,"Identifiant",login);Add(p,"Nom",name);password.UseSystemPasswordChar=true;Add(p,"Mot de passe",password);var b=new Button{Text="Créer l'administrateur",Dock=DockStyle.Fill};b.Click+=async(_,_)=>{try{User=await this.auth.CreerPremierAdministrateurAsync(login.Text,name.Text,password.Text);DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex.Message,"Validation",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};p.Controls.Add(b,0,4);p.SetColumnSpan(b,2);Controls.Add(p);}
    static void Add(TableLayoutPanel p,string label,TextBox box){p.Controls.Add(new Label{Text=label,Anchor=AnchorStyles.Left,AutoSize=true});box.Dock=DockStyle.Fill;p.Controls.Add(box);}
}

public sealed class LoginForm : Form
{
    readonly AuthentificationService auth; readonly TextBox login=new(),password=new(); public Utilisateur? User{get;private set;}
    public LoginForm(AuthentificationService auth){this.auth=auth;Text="Connexion";Width=420;Height=280;StartPosition=FormStartPosition.CenterScreen;var p=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(25),ColumnCount=2,RowCount=3};p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,35));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,65));p.Controls.Add(new Label{Text="Identifiant",Anchor=AnchorStyles.Left,AutoSize=true},0,0);p.Controls.Add(login,1,0);p.Controls.Add(new Label{Text="Mot de passe",Anchor=AnchorStyles.Left,AutoSize=true},0,1);password.UseSystemPasswordChar=true;p.Controls.Add(password,1,1);var b=new Button{Text="Se connecter",Dock=DockStyle.Fill};b.Click+=async(_,_)=>{User=await this.auth.ConnexionAsync(login.Text,password.Text);if(User is null)MessageBox.Show("Identifiants invalides.","Connexion",MessageBoxButtons.OK,MessageBoxIcon.Warning);else{DialogResult=DialogResult.OK;Close();}};p.Controls.Add(b,0,2);p.SetColumnSpan(b,2);Controls.Add(p);}
}
